#!/usr/bin/env bun
import{text}from"node:stream/consumers";function parseHookJson(raw){return JSON.parse(raw)}async function runHookPlugin({parser,handler,writer}){let output=await handler(parser(await text(process.stdin)));process.stdout.write(writer(output))}const ALLOW_PATTERNS=[/^[a-zA-Z0-9_/.~"'-]/];function isAllowed(command){return ALLOW_PATTERNS.some(function(pattern){return pattern.test(command)})}const SKIP_PATTERNS=[/\b(xxd|hexdump|od|base64|tar|gzip|gunzip|zip|unzip|bzip2|xz|zstd)\b/,/>\s*[^\s|&;]/,/\bfilter\.(mjs|ts)\b/,/___BOF_EC:/,/&\s*$/,/\b(nohup|setsid)\b/,/\b(docker|podman)\s+(exec|run)\b.*-[a-z]*[it]/,/\bbun\s+build\b/,/\$\(/,/`[^`]+`/,/[<>]\(/,/<<[<-]?\s*\S/,/\b(cd|pushd|popd|export|unset|source)\b/,/^\.\s/,/\beval\b/];function shouldSkip(command){return SKIP_PATTERNS.some(function(pattern){return pattern.test(command)})}function isBashToolInput(input){return typeof input.command==`string`}function bashOutputFilterHandler(event){if(event.tool_name!==`Bash`||!isBashToolInput(event.tool_input))return{};let bashInput=event.tool_input;if(!isAllowed(bashInput.command)||shouldSkip(bashInput.command))return{};let filterPath=import.meta.url.endsWith(`.mjs`)?`${import.meta.dirname}/filter.mjs`:`${import.meta.dirname}/filter.ts`,wrappedCommand=`set -o pipefail && ${bashInput.command} 2>&1 | bun ${filterPath} && true`;return{hookSpecificOutput:{hookEventName:`PreToolUse`,updatedInput:{...bashInput,command:wrappedCommand}}}}function bashOutputFilterParser(raw){return parseHookJson(raw)}function bashOutputFilterWriter(output){return JSON.stringify(output)}await runHookPlugin({parser:bashOutputFilterParser,handler:bashOutputFilterHandler,writer:bashOutputFilterWriter});export{};